class runner(object):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    MAX_RETRIES = 3
    RETRY_INTERVAL = 3

    _wtsemu_egate = None
    _wtsemu_edaemon = None
    _wtsemu_egate_controller = None
    _wtsemu_ssh_alias = None

    def _configure_wtsemu_remote_process(
        self,
        component_cls,
        self_attr_name,
        ssh_alias,
        directory_path,
        port,
        sudo_password,
        nostats,
    ):
        ssh_connection = managed_from_aliased(ssh_alias)
        component = component_cls(
            ssh_connection,
            directory_path,
            port,
            sudo_password=sudo_password,
            nostats=nostats,
        )
        setattr(self, self_attr_name, component)

    def configure_wtsemu_egate(
        self,
        egate_ssh_alias,
        directory_path,
        port,
        sudo_password=None,
        nostats=False,
    ):
        """
        configure wtsemu Egate service

        :param egate_ssh_alias: String: Egate ssh connection alias
        :param directory_path: String: Egate program path
        :param port: Int: Egate port.
        :param sudo_password: String: (Optional)Sudo command password.
        """
        self._wtsemu_ssh_alias = egate_ssh_alias
        self._configure_wtsemu_remote_process(
            Egate,
            "_wtsemu_egate",
            egate_ssh_alias,
            directory_path,
            port,
            sudo_password,
            nostats=nostats,
        )

    def configure_wtsemu_edaemon(
        self, edaemon_ssh_alias, directory_path, port, sudo_password=None
    ):
        """
        configure wtsemu Edaemon service

        :param edaemon_ssh_alias: String: Edaemon ssh connection alias
        :param directory_path: String: Edaemon program path
        :param port: Int: Edaemon port.
        :param sudo_password: String: (Optional)Sudo command password.
        """
        self._configure_wtsemu_remote_process(
            Edaemon,
            "_wtsemu_edaemon",
            edaemon_ssh_alias,
            directory_path,
            port,
            sudo_password,
            nostats=False,
        )

    def start_wtsemu(self, egate_console_ip, egate_port, egate_timeout=5.0):
        """
        telnet to wtsemu egate console, create setup and teardown relationship

        :param egate_console_ip: String: Ip of egate console ,will be 0 only if robot case/keyword and egate
                                         are on the same equipment. Otherwise the full IP should be given.
        :param egate_port: String: Port number of configured egate process.
        :param egate_timeout: Int: (optional) timeout of connect to egate.
        :return:
        """
        if self._wtsemu_egate is None or self._wtsemu_edaemon is None:
            exc_msg = (
                "one or more of the required components "
                "has not been configured."
            )
            raise RuntimeError(exc_msg)

        egate_timeout = float(egate_timeout)
        egate_port = int(egate_port)
        egate_telnet = Telnet(egate_console_ip, egate_port, egate_timeout)
        egate_controller = EgateConsole(
            egate_telnet, self._wtsemu_edaemon, self._wtsemu_egate
        )
        wtsemu_egate_controller = WtsEmulator(egate_controller)

        for _ in range(self.MAX_RETRIES):
            try:
                wtsemu_egate_controller.setup()
                break
            except socket_error:
                logger.info(
                    "Failed to create a connection, retry in {}s.".format(
                        self.RETRY_INTERVAL
                    )
                )
                sleep(self.RETRY_INTERVAL)
        else:
            raise socket_error(
                "Failed to create a connection after trying {} times.".format(
                    self.MAX_RETRIES
                )
            )
        self._wtsemu_egate_controller = wtsemu_egate_controller

    def kill_wtsemu_edaemon(
        self, edaemon_port, connection=None, sudo=True, sudo_password=None
    ):
        """
        kill edaemon on wtsemu with given edaemon port number.

        :param edaemon_port: Int: target edaemon port number
        :param connection: String: (Optional)connection alias of target vm.
                           Will use wtsemu as default connection.
        :param sudo: Bool: (Optional)whether to kill with sudo.
        :param sudo_password: String: (Optional) password of root user.
        """
        if connection:
            alias = connection
        else:
            alias = self._wtsemu_ssh_alias
        WtsEmuKiller.kill_program(
            target="edaemon",
            target_port=edaemon_port,
            ssh_alias=alias,
            sudo=sudo,
            sudo_password=sudo_password,
        )

    def kill_wtsemu_egate(
        self, egate_port, connection=None, sudo=False, sudo_password=None
    ):
        """
        kill egate on wtsemu with given egate port number.

        :param egate_port: Int: target egate port number
        :param connection: String: (optional)connection alias of target vm.
                           Will use wtsemu as default connection.
        :param sudo: Bool: (Optional)whether to kill with sudo.
        :param sudo_password: String: (Optional) password of root user.
        """
        if connection:
            alias = connection
        else:
            alias = self._wtsemu_ssh_alias
        WtsEmuKiller.kill_program(
            target="egate",
            target_port=egate_port,
            ssh_alias=alias,
            sudo=sudo,
            sudo_password=sudo_password,
        )

    def stop_wtsemu(self):
        """
        Stops every software component.
        """
        if self._wtsemu_egate_controller is None:
            msg = (
                "wtsemu egate controller is not initialized - cannot teardown."
            )
            logger.warn(msg)
        else:
            self._wtsemu_egate_controller.teardown()

    def read_wtsemu_output(self):
        """Read at least one byte from Egate console, unless EOF is hit.

        Returns empty string if EOF is hit. Blocks if no data is immediately
        available.
        """
        return self._wtsemu_egate_controller.read_egate_output()

    def read_wtsemu_output_until(self, expected, timeout):
        """Read output until the expected string is matched
        or the timeout is exceeded.

        Timeout is specified in seconds.
        The expected string is included in the returned data.

        Raises EOFError if connection is closed during reading and the expected
        String can't be matched in the buffer.
        Raises socket.timeout if specified timeout is exceeded.

        :param expected: String: expected output in egate console.
        :param timeout: Int: Timeout of read output.
        :return:
        """
        timeout = float(timeout)
        wts = self._wtsemu_egate_controller
        return wts.read_egate_output_until(expected, timeout=timeout)

    def read_wtsemu_output_until_re(self, expected, timeout):
        """Read output until the expected regular expression is matched
        or the timeout is exceeded.

        Timeout is specified in seconds.
        The expected string is included in the returned data.

        Raises EOFError if connection is closed during reading and the expected
        regular expression can't be matched in the buffer.
        Raises socket.timeout if specified timeout is exceeded.

        :param expected: String: Regular expression of expected output in egate console.
        :param timeout: Int: Timeout of read output.
        :return:
        """
        timeout = float(timeout)
        wts = self._wtsemu_egate_controller
        return wts.read_egate_output_until_re(expected, timeout=timeout)

    def read_wtsemu_output_until_prompt(self, timeout):
        """Read output until the prompt string is hit ("EGATE> ").

        Timeout is specified in seconds.
        The prompt string will be stripped from the returned output.

        Raises EOFError if connection is closed during reading and the prompt
        string is not in the buffer.
        Raises socket.timeout if specified timeout is exceeded.
        """
        timeout = float(timeout)
        wts = self._wtsemu_egate_controller
        return wts.read_egate_output_until_prompt(timeout=timeout)

    def assert_is_in_wtsemu_output(self, expected, msg):
        """Read output, (do a 'read_egate_output()'), and assert that the
        expected string is contained within the captured data.

        Raises AssertionError if the expected string is not in the output.
        If 'msg' argument is specified, the AssertionError will contain that
        message.

        Other raised exceptions and returned value are the same as when using
        'read_wtsemu_output()'.

        :param expected: String: expected output in egate console.
        :param msg: String: specific string added in assertionError.
        :return:
        """
        output = self.read_wtsemu_output()
        if msg is not None:
            assert expected in output, msg
        else:
            assert expected in output
        return output

    def reset_wtsemu_cfg(self):
        """
        remove configure of wtsemu egate controller
        """
        self._wtsemu_egate_controller.remove_configure()

    def read_wtsemu_log(self, log_path, expected):
        """
        check logs in wtsemu,return log file contents.
        """
        return self._wtsemu_egate_controller.read_wtsemu_log(
            log_path=log_path,
            ssh_alias=self._wtsemu_ssh_alias,
            expected=expected,
        )

