    def modify_cfg_file(input_cfg_file, output_cfg_file, parameters_list):
        """
        Modifies provided CFG file and saves it to provided path.

        :param input_cfg_file: path to CFG file
        :param output_cfg_file: path where modified CFG file will be stored
        :param parameters_list: list of dictionaries with values to modify
        :return:
        """
        cfg_operation = CFGOperations()
        cfg_operation.modify_file(
            input_cfg_file, output_cfg_file, parameters_list
        )

