    def amf_param(self, **kwargs):
        """
        :param id: identifier of AMF
        :param ignore_ng: (Optional)
        :param indirect_data_forwarding: (Optional) If set to on, Indicates supp
               ort for indirect data forwarding during inter RAT handover to LTE
        :param full_nas_auth: (Optional) Indicates, will AMF go through NAS Auth
               entication and SecurityMod phases in any case or will try to skip them
        :param ng_setup_failure_time_to_wait: (Optional) Time to wait IE value t
               o be included forced NG SETUP FAILURE message (in seconds)
        :param reg_procedure_sequence: (Optional) Message scenarios of Initial C
               ontext Setup Request and DL NAS Transport (NAS: Registration Accept)
        :param ambr_remove: (Optional) NGAP messages in which UE AMBR shall not
               be included. This argument covers only the ICS, the PDU SESSION SETUP REQUEST and
                the DL NAS TRANSPORT. default =&gt; UE AMBR (DL/UL) shall only be included in th
               e first NGAP where a PDU Session is being setup. all =&gt; UE AMBR shall not be i
               ncluded in any of above messages. none =&gt; UE AMBR shall be included in all the
                above messages. other value(s) =&gt; UE AMBR shall be included in all possible m
               essages except the set of messages explicitly indicated in this argument
        :param nea: (Optional) NR Encryption Algorithms
        :param nia: (Optional) NR Integrity Algorithms
        :param action: (Optional) Specifies what action will be done when the nth occurence is met
        :param if_condition: (Optional) (!!!Equals to `if` in egate command!!!) if condition ,perform related actions
        :param empty_pdu_session_list: (Optional) If enabled, Initial Context Se
               tup Request in response to Service reqeust from UE, will not carry PDU sessions o
               r Service accept
        :param order_backupamfs: (Optional) determines the order in which backup
               amfs (for GUAMIs) are included in the NG Setup Response message
        :param T3550: (Optional) Wait for Registration Complete
        :param T3560: (Optional) Wait for Authentication Response / Authenticati
               on Failure / Security Mode Complete / Security Mode Reject
        :param T3522: (Optional) Wait for Deregistration Accept
        :param T3555: (Optional) Wait for Nas Config Update Complete
        :param T3570: (Optional) Wait for Identity Response
        :param voice_fallback: (Optional) enables Redirection via Voice fallback
                to LTE Procedure for gNB. If set to 'on', the value of the 'Redirection for Voic
               e EPS Fallback' IE is set to 'possible', If set to 'off', the value is set to 'no
               t-possible'. If set to 'none', the 'Redirection for Voice EPS Fallback' IE is not
                included. The 'Redirection for Voice EPS Fallback' IE is applicable for the Init
               ial Context Setup Request, Handover Request and Path Switch Request Acknowledge m
               essages. If this parameter is not configured, the behaviour is the same as the 'n
               one' option.
        :param send_ics_registration: (Optional) Specifies that ICS is always se
               nt in response to registration request in initial UE message
        :param emergency_service_fallback: (Optional) enables emergency service fallback
        :param target_cn: (Optional) Target Core network for emergency fallback
        :param ims_voice_3gpp: (Optional) Indicates the support of IMS voice over PS session over 3GPP access
        :param bypassAuth_nullSecurity: (Optional) Bypass the UE authentication
               with null NR integrity and null NR security algorithms.
        :param intra5gs_data_forwarding: (Optional) if set to off, indirect data
                forwarding for intra 5g handover is not supported
        :param support_guami_unavailability: (Optional) If enabled, AMF status I
               ndication messages can be triggered towards the gNb for specified GUAMIs which wo
               uld mark the GUAMIs as unavailable
        :param release_old_ue_context: (Optional) Trigger NGAP: UE CONTEXT RELEA
               SE COMMAND for old UE-associated logical NG-connection when new connection is est
               ablished via the NGAP: INITIAL UE MESSAGE.
        :param include_reg_accept_with_ics: (Optional) If set to on, Registratio
               n Accept will be included as a nas-pdu along with ICSR(Initial Context Set-Up Req
               uest) message when ICS is done as part of registration.
        :param allocate_e_rab_id: (Optional) (!!!Equals to `allocate_e-rab_id` i
               n egate command!!!) Generates and includes e-rab ids for qos flows in PDU session
               s if set to true. This param is applicable at PDU session level. Once set, this i
               s applicable to all subsequent PDU sessions.
        :param reuse_ran_ue_ngap_id_on_ng_reset: (Optional) Allow ran ue ngap ids to be reused after ng reset
        :param allow_nas_reroute_same_setid: (Optional) Specifies if a NAS messa
               ge can be rerouted to a different AMF with the same set id as the source AMF. Thi
               s parameter is applicable only when the action is 'reroute'
        """

        self._wtsemu_egate_controller.egate_command_executor(
            "amf_param", **kwargs
        )

