    def enb_set(self, **kwargs):
        """
        :param s1: List of eNB S1 IP addresses (IPv4/IPv6/Dual-stack) for extern
               al eNB (up to 10 e.g. for RAN sharing operators); single IP for internal (IPv4/IP
               v6, in the case of Dual-stack IP only the IPv6 part is used).
        :param plmn: Public Land Mobile Network ID
        :param id: (Optional) Specified eNB id
        :param type: (Optional) Simulation type (format is type:measurement)
        :param daemon: (Optional) Simulated edaemon ip address and port
        :param s1_proxy: (Optional) S1 IP address of a proxy by which MMEs will
               see this eNB simulator, it could be IP of some external tool e.g. SXAP. Parameter
                valid only for a simulated eNB
        :param s1_multihome_ip: (Optional) List of eNB S1 Multihoming IP address
               es (IPv4/IPv6/Dual-stack) for external eNB; single IP for internal (IPv4/IPv6, in
                the case of Dual-stack IP only the IPv6 part is used). Each address on the list
               corresponds to the S1 address at the same position on the S1 addresses list and t
               his pair forms SCTP multihoming addresses for an S1 connection of one transport n
               etwork. If for a given transport network (e.g. used for some RAN sharing operator
               ) a multihoming connection is not configured then use the invalid IP address (0.0
               .0.0, you don't need to do it for the last positions on the list).
        :param s1_port: (Optional) eNB S1 listening SCTP port
        :param x2_multihome_ip: (Optional) X2 multihoming (secondary) IP address
               ; by default, when the X2-C is not set, the same as RAN multihome IP address (S1-
               C multihoming)
        :param s1u: (Optional) S1U IP address for connecting to EPC SGW
        :param x2: (Optional) List of X2-C IP addresses (Ipv4/Ipv6/Dual-stack) a
               nd ports for external ENB/GNB, single IP for internal (simulated). By default, th
               e same as S1-C IP address
        :param x2_proxy: (Optional) X2 IP address of a proxy to which other eNBs
                will connect and through which this eNB simulator is seen, it could be IP of som
               e external tool e.g. SXAP. Parameter valid only for a simulated element
        :param x2u: (Optional) List of X2-U IP addresses for external ENB/GNB, s
               ingle IP for internal (simulated). If not set the IP of X2-C interface is assumed
                as X2-U IP (and if X2-C is not set the S1-C IP is used)
        :param x2_peers: (Optional) X2 peers to establish X2 link on startup with eNB
        :param xp_management: (Optional) Allows Xp based applications
        :param xp: (Optional) Xp IP address and port; by default, the same as primary RAN IP address
        :param xpu: (Optional) XpU IP address (used if value differ from IP of Xp)
        :param xp_multihome_ip: (Optional) Xp multihome IP address; by default, the same as RAN multihome IP address
        :param xp_udp_dscp: (Optional) UDP Differentiated Services Code Point for Xp
        :param xp_sctp_dscp: (Optional) SCTP Differentiated Services Code Point for Xp
        :param reuse_xpu_ipport: (Optional) Toggle to allow the reuse of the XPU IP/port
        :param xpu_snd_buff_cfg: (Optional) XPU buffer size for sending data
        :param xpu_rcv_buff_cfg: (Optional) XPU buffer size for receiving data
        :param local_crm: (Optional) Allow CRM creation
        :param nssai: (Optional) Set of Single Network Slice Selection Assistanc
               e Information (syntax and value range: nssai=sst:sd where sst=0..0xFF and sd=0..0
               xFFFFFF). If sd part is not configured, the value 0 is used. If set to 0xFFFFFF,
               the sd part is not be included
        :param mme: (Optional) list of MME/s that the eNB should associate with
        :param enb_id_macro: (Optional) Macro eNB-ID for multi-cell configuration (5 hex symbols, 20 bits)
        :param enb_id_home: (Optional) Home eNB-ID for single-cell configuration (7 hex symbols, 28 bits)
        :param rsrq: (Optional) RSRQ threshold to trigger handover for event A4
        :param a3_offset: (Optional) Offset to trigger handover for event A3
        :param name: (Optional) eNB name
        :param gtpu_read_packets_threshold: (Optional) Read Packets Threshold for GTP-U link; 0 means no threshold
        :param s1u_snd_buff_size: (Optional) S1U buffer size for sending data
        :param s1u_rcv_buff_size: (Optional) S1U buffer size for receiving data
        :param x2u_snd_buff_size: (Optional) X2U buffer size for sending data
        :param x2u_rcv_buff_size: (Optional) X2U buffer size for receiving data
        :param proxy_snd_buff_size: (Optional) Proxy buffer size for sending data
        :param proxy_rcv_buff_size: (Optional) Proxy buffer size for receiving data
        :param proxy_read_packets_threshold: (Optional) Read proxy packets threshold
        :param reuse_x2u_ipport: (Optional) Toggle to allow the reuse of the X2U IP/port
        :param auto_x2_ipsec: (Optional) Automatically configure X2 IPsec connec
               tions with the real eNBs, based on an S1 ANR procedure
        """

        self._wtsemu_egate_controller.egate_command_executor(
            "enb_set", **kwargs
        )

