    def gnb_xn_ho_report_param(self, **kwargs):
        """
                :param t_gNB_id: Local identifier for gNB
        Note: Target gNB Id for handover procedure

                :param s_gNB_id: Local identifier for gNB
        Note: Source gNB Id for handover procedure

                :param ho_report_type: Handover Report Type. Values are enumerated{HO to
                       o early = 0, HO to wrong cell = 1, Inter-system ping-pong }
                :param source_cell_cgi: NG-RAN Cell Id of source cell for handover procedure.
        NR Cell Id belonging to a PLMN. Input format for eGate is MCC:MNC | CI.
        where CI is Cell Identity of max length 14 bits.
        Note : Format of the NRCGI is:
        MCC:MNC | NCI.
        MCC :  3 digits.
        MNC :  2 or 3 digits
        NCI= gNB Id + Cell Id
        gNB Id : Minimum 22 bits and Maximum 32 bits
        Cell Id: Minimum 4 bits and Maximum 14 bits

                :param target_cell_cgi: NG-RAN Cell Id of source cell for handover procedure.
        NR Cell Id belonging to a PLMN. Input format for eGate is MCC:MNC | CI.
        where CI is Cell Identity of max length 14 bits.
        Note : Format of the NRCGI is:
        MCC:MNC | NCI.
        MCC :  3 digits.
        MNC :  2 or 3 digits
        NCI= gNB Id + Cell Id
        gNB Id : Minimum 22 bits and Maximum 32 bits
        Cell Id: Minimum 4 bits and Maximum 14 bits

                :param ho_cause: Cause
                :param source_cell_c_rnti: (Optional) (!!!Equals to `source_cell_c-rnti` in egate command!!!) C-RNTI
                :param mobility_information: (Optional) Bit index 0(LSB bit) , if set to value:
        0 - Indicates RSRP threshold was used to trigger Handover
        1 - Indicates RSRQ threshold was used to trigger Handover

                :param reestablishment_cell_cgi: (Optional) NR Cell Id belonging to a PL
                       MN. Input format for eGate is MCC:MNC | CI.
        where CI is Cell Identity of max length 14 bits.
        Note : Format of the NRCGI is:
        MCC:MNC | NCI.
        MCC :  3 digits.
        MNC :  2 or 3 digits
        NCI= gNB Id + Cell Id
        gNB Id : Minimum 22 bits and Maximum 32 bits
        Cell Id: Minimum 4 bits and Maximum 14 bits

        """

        self._wtsemu_egate_controller.egate_command_executor(
            "gnb_xn_ho_report_param", **kwargs
        )

