    def ul_ue_beam_pos_nr(self, **kwargs):
        """
        :param profile_id: Test profile id
        :param mode: (Optional) 0: Fixed 1:Horizontal sweeping 2:Continuous horizontal sweeping
        :param delete: (Optional) delete the test profile,Options : yes|no; true
               |false; 1|0 ; on|off and Set it to true|yes|on|1 to delete the profile.
        :param num_beam_paths: (Optional) 2 paths considered per Beam. +ve Polar
               ization and -ve polarization [CB010708] up to 4 Beams i.e 8 Beam paths are possib
               le in this featurevalue is 0: This is used in special cases.
        :param azimuth: (Optional) Angle In horizontal planeIn case of 16 Beam p
               aths: 1st 8 entries indicates the Angle for +ve polarization and 2nd 8 entries in
               dicate the power for -ve polarizationIn case of 8 Beam paths: 1st 4 entries indic
               ates the Angle for +ve polarization and 2nd 4 entries indicate the power for -ve
               polarization and so on...Resolution for the azimuth angle is 1 degree.
        :param zenith: (Optional) Angle in vertical plane - In case of 16 Beam p
               aths: 1st 8 entries indicates the Angle for +ve polarization and 2nd 8 entries in
               dicate the power for -ve polarization In case of 8 Beam paths: 1st 4 entries indi
               cates the Angle for +ve polarization and 2nd 4 entries indicate the power for -ve
                polarization and so on...Resolution for the zenith angle is 1 degree.CB010708-C:
                In case of Beam sweeping this IE is not used, Instead startDegree and endDegree
               are used for Azimuth
        :param power: (Optional) Power per Beam path in dBFs.In case of 16 Beam
               paths: 1st 8 entries indicates the power for +ve polarization and 2nd 8 entries i
               ndicate the power for -ve polarizationIn case of 8 Beam paths: 1st 4 entries indi
               cates the power for +ve polarization and 2nd 4 entries indicate the power for -ve
                polarization and so on...supported range of power in 7.2a is -849 to -130 only t
               hough egate allows range from -1200 to -130In 7.2e supported range of power is -1
               200 to -130
        :param dtx_start_srs: (Optional) Indicates the count of Periodic SRS Sen
               dReq messages after which DTX simulation starts
        :param num_dtx_srs: (Optional) Number of time DTX is simulated for Periodic SRS
        :param step_size: (Optional) Step size to be used during sweeping. Both
               +ve and -ve step size are supported. Resolution is 1 Degree.
        :param start_degree: (Optional) startDegree in Azimuth
        :param end_degree: (Optional) endDegree in Azimuth
        :param sweep_interval: (Optional) Count of SRS Periodicity after which the Azimuth is shifted by a stepSize.
        :param sweep_count: (Optional) Sweeping stop after this count or after t
               he boundary (endDegree) reaches. which ever occur first
        :param correlation_mode: (Optional) Correlation Mode : FIXED|VARIABLE
        :param num_subband_info: (Optional) Number of Subband Info : 1,2,4
        :param correlation: (Optional) Magnitude of the coefficient between the
               Channel estimate (CE) vector&lt;br&gt;(at the middle PRB of the middle sub band u
               sing mid-PRB method)&lt;br&gt;of different SRS ports at different time periods&lt
               ;br&gt;&lt;br&gt;Granularity is 0.01
        :param num_interfered_bf_subband: (Optional) Number of interfered BF subband
        :param interfered_srs_subband: (Optional) Interfered SRS subband
        :param start_correlation: (Optional) valid only if the mode is VARIABLE&
               lt;br&gt;Same value applies to all SRS ports
        :param end_correlation: (Optional) valid only if the mode is VARIABLE&lt
               ;br&gt;Same value applies to all SRS ports
        :param correlation_step_size: (Optional) valid only if the mode is VARIA
               BLE&lt;br&gt;Same value applies to all SRS ports
        :param correlation_step_count: (Optional) valid only if the mode is VARI
               ABLE&lt;br&gt;Value in terms of number of SRS Periodicities.
        :param srs_transmit_power_per_port: (Optional) The transmit power per SR
               S port of UE. Multiplicity can be 1, 2 or 4
        """

        self._wtsemu_egate_controller.egate_command_executor(
            "ul_ue_beam_pos_nr", **kwargs
        )

