    def rimrs_testmode_nr(self, **kwargs):
        """
        :param profile_id: Test profile id
        :param delete: (Optional) delete the RIM-RS test profile.
        :param config_mode: (Optional) This parameter specifies the rim-rs configuration mode. Default:0.
        :param enable_auto_propagation_delay: (Optional) Flag to enable automati
               c propagation delay to avoid overlap of multiple RIM-RS
        :param victim_cell: (Optional) local identifier for victim cell.
        :param aggressor_cell: (Optional) local identifier for aggressor cell.
        :param rsSetId: (Optional) rsSetId value configured on the victim gNB for remote interference management.
        :param numRsSetId: (Optional) Number of rsSetId values starting from "rsSetId".
        :param rimRsType: (Optional) This parameter specifies the type of RIM-RS
                to be transmitted.1:RsType1, 2:RsType2, 3:RsType1AndRsType2 default: 1.
        :param rsNearFarConfig: (Optional) This parameter specifies the slot use
               d for RIM-RS transmission in one uplink-downlink switching period,0: near only, 1
               : near -far config1, 2: near-far config2. default: 0.
        :param propagation_delay: (Optional) Propagation delay in symbols,this p
               arameter specifies the propagation delay to be applied on RIM-RS received from vi
               ctim cell to aggressor cell. default: 4.
        :param rsEnoughIndicationType: (Optional) This parameter used to configu
               re enough indication type for RS1 transmission for given set ID0 - Not Enough Mit
               igation 1 - Enough Mitigation
        :param rimRsTxPower: (Optional) Transmit power of RIM-RS Type1 expressed
                in dBFS (step of 0.1 dBFS),value in dBFS = rimRsTxPower/ 10. default:-330.
        :param rimRsTxPowerRS2: (Optional) Transmit power of RIM-RS Type2 expres
               sed in dBFS (step of 0.1 dBFS),value in dBFS = rimRsTxPower/ 10. default:-330.
        :param rsType1NScId: (Optional) List of seeds for RIM-RS Type1 sequences generation.
        :param rsType2NScId: (Optional) List of seeds for RIM-RS Type2 sequences generation.
        :param numRbForRs: (Optional) Number of resource blocks for RIM-RS.default: 48.
        :param rsPattern1Period: (Optional) Uplink-downlink switching period for
                pattern 1;25 → 2.5ms;30 → 3ms;50 → 5ms.
        :param rsPattern2Period: (Optional) Uplink-downlink switching period for
                pattern 2;0 → (single pattern, not valid);20 → 2ms;25 → 2.5ms default: 0.
        :param repetitionRsType1: (Optional) Number of consecutive uplink-downlink periods for RIM-RS type 1,default:4.
        :param repetitionRsType2: (Optional) Number of consecutive uplink-downlink periods for RIM-RS type 2,default:4.
        :param rim_framework: (Optional) This parameter specifies the rim-framework to be used. default: 0.
        :param factorRsSequence: (Optional) Multiplier factor for RIM-RS type 1 sequence initialization.
        :param factorRsSequenceRS2: (Optional) Multiplier factor for RIM-RS type 2 sequence initialization.
        :param offsetRsSequence: (Optional) Offset for RIM-RS type 1 sequence initialization.
        :param offsetRsSequenceRS2: (Optional) Offset for RIM-RS type 2 sequence initialization.
        :param startRbForRs: (Optional) List of starting RB for each frequency r
               esource assigned to RIM-RS transmission.
        :param numRsType1SetId: (Optional) Total number of setIDs used for RIM-R
               S type 1 configured in the network.default:1048576.
        :param numRsType2SetId: (Optional) Total number of setIDs used for RIM-R
               S type 2 configured in the network.default:1048576.
        :param rsEnoughIndication: (Optional) This parameter is used to configur
               e RIM-RS enough indication functionality.0: Disabled 1: Enabled
        :param globalF0ForRs: (Optional) Global F0 for RIM-RS
        :param startFreqOffsetForRs: (Optional) RIM-RS starting frequency offset
        :param leap_seconds_auto: (Optional) This parameter is used to automatic
               ally adjust the leap seconds based on API provided by BBP. default:on.
        :param leap_seconds_manual: (Optional) This parameter is used to manuall
               y add the leap seconds starting from 1st Jan 1900.deafault:27.
        :param rimrs_boundary_alignment: (Optional) This parameter is used to al
               ign RIM-RS time boundary between AP and gNB.0: Leading 1: Lagging
        :param cell_id: (Optional) This parameter indicates cell configuration o
               f victim cell or aggressor cell based on gNB configuration.
        :param antStream: (Optional) Indicating which Antenna will be used to tranmit RIM-RS.
        :param numCeAxcIndex: (Optional) Number of ceAxcIndex that are valid for this transmission request
        :param ceAxcIndex: (Optional) Set of eAxC indices to be used for the transmission on eCPRI Fronthaul.
        :param patternId: (Optional) Beam patternIds to be used for transmission
                and the eCPRI control message generation.
        """

        self._wtsemu_egate_controller.egate_command_executor(
            "rimrs_testmode_nr", **kwargs
        )

