    def csi_override_testmode_nr(self, **kwargs):
        """
        :param profile_id: New CSI Report Override EGAT command designed in such
                a way that for each UE there will be default Profile (profile_id=1) created and
               activated (Without the CSI test mode configured for a user yet) during User Setup
               .Default profile is applicable to all the cells (including primary and secondary
               cells). Default profile is applicable for all cells that get attached during Init
               ial access or SgNB addition.It is up to tester can change the CSI parameters of d
               efault profile (profile_id=1) much before UE registration (ue_attach in case of N
               SA & ue_register in case of SA).Recommendation is to create new profiles after ue
               _registration so that profile ID=1(default) is intact
        :param delete: (Optional) delete the test profile,Options : yes|no; true
               |false; 1|0 ; on|off and Set it to true|yes|on|1 to delete the profile.
        :param cqi: (Optional) List of 255(MAX_NUM_OF_CQI_NR) CQI values of range(0 to 15) to report in NR.
        :param pmi: (Optional) List of PMI values to report in NR. Codebook inde
               x values are valid up to 32 port CSI-RS antenna ports.&lt;br&gt;1) 2-port CSI-RS
               ports, codebookType is set to twoTX_CodebookSubsetRestriction, pmi value can be 0
               ..3 for Rank1 and 0..1 for Rank2&lt;br&gt;2) For other configurations as below&lt
               ;br&gt;a) 4-port CSI-RS, codebookType “two_one_TypeI_SinglePanel_Restriction”&lt;
               br&gt;b) 8-port CSI-RS codebookType “two_two_TypeI_SinglePanel_Restriction” OR “f
               our_one_TypeI_SinglePanel_Restriction”&lt;br&gt;c)32-port CSI-RS codebookType “ei
               ght_two_TypeI_SinglePanel_Restriction”&lt;br&gt;then pmi value should be treated
               as following 16-bit fields&lt;br&gt;MSB------------------------------------------
               ----------------------------LSB&lt;br&gt;Padding bits (4 bits) |i1.1(5 bits) |i1.
               2(3 bits) |i1.3(2 bits) |i2(2 bits)
        :param ri: (Optional) List of up to 16 Rank indicators(MAX_NUM_OF_RI_NR)
                where as ri value range is 0 to 3 to be reported in NRDefault ri value will be 0
        :param cri: (Optional) CSI Resource Indicator
        :param li: (Optional) List of up to 4 Resources indicators to report in NR
        :param cqi_mode: (Optional) CQI Mode
        :param pmi_mode: (Optional) PMI Mode
        :param ri_mode: (Optional) RI Mode
        :param cri_mode: (Optional) CRI Mode
        :param li_mode: (Optional) LI Mode
        :param cqi_min: (Optional) minimum CQI value while cqi_mode = oneway or oscillating
        :param cqi_max: (Optional) maximum CQI value while cqi_mode = oneway or oscillating
        :param cqi_step: (Optional) step CQI value while cqi_mode = oneway or oscillating
        :param cqi_period: (Optional) Cqi period - Number of CSI reports before
               changing the value of CQI. 1st value provided in CQI list is base value
        :param overheating_cnt: (Optional) Specifies number of times CQI=0 needs
                to be sent to gNB by L2SM for overheating.If count not specified for oscillating
                mode, then the default 5 is assigned.
        :param pmi_period: (Optional) Pmi period - Number of CSI reports before
               changing the value of PMI to 'other' values
        :param ri_period: (Optional) Ri Period - Number of CSI reports before ch
               anging the value of RI to 'other' values
        :param cri_period: (Optional) Cri Period - Number of CSI reports before
               changing the value of CRI to 'other' values
        :param li_period: (Optional) Li Period - Number of CSI reports before ch
               anging the value of LI to 'other' values
        :param cqi_period_list: (Optional) Cqi period List - List of 255(MAX_NUM
               _OF_CQI_NR) CQI periods - Number of CQI reports before switching to the next valu
               e(range 1 to 65535) of cqi list.
        :param ri_period_list: (Optional) ri period List - List of 16(MAX_NUM_OF
               _RI_NR) RI periods - Number of RIreports before switching to the next value(range
                1 to 65535) of ri list.
        :param drop_periodic_csi_on_pusch: (Optional) This IE indicates number o
               f times to drop the Periodic CSI on PUSCH.0: No drop of Periodic CSI.Non-Zero val
               ue indicates number of times to drop periodic CSI.Default value is 0
        """

        self._wtsemu_egate_controller.egate_command_executor(
            "csi_override_testmode_nr", **kwargs
        )

