    def upf_param(self, **kwargs):
        """
               :param id: identifier of UPF
               :param end_markers: (Optional) Number of end markers that should be sent
                       during HO. The value 0 applies only to inter-RAT direct data forwarding handover
                       (5G to LTE). A value of 0 indicates that end markers are not sent for either PDU
                       level forwarding or DRB level forwarding
               :param modify_tunnel_info: (Optional) Enables/disables the modification of TEID during XN HO
               :param end_markers_delay: (Optional) Time (in milliseconds) to wait afte
                      r reception of N4 Session Modification at the UPF to send end markers to the sour
                      ce gNB
               :param ForwardTunnel_EM_timeout: (Optional) Time (in seconds) to wait fo
                      r the reception of end markers from the source gNB
               :param skip_echo_req: (Optional) Skip processing of GTP-U echo request on specified GTP-U path.
        skip_echo_req=local_ip,remote_ip,num_msg_to_skip
        local_ip - local endpoint ip address
        remote_ip - remote endpoint ip address
        num_msg_to_skip - Number of GTPU echo request message to skip
        Note: This option cannot be set if delay_echo_resp is already set for same path
                      . If WTS is not in active state, this option will not be effective
               :param gtpu_error_during_xn_handover: (Optional) Specifies that a GTP-U
                      Error Indication will be sent on GTP Tunnel belonging to all PDU Sessions, toward
                      s target gnb during XN handover
               :param send_end_markers_qfi_extn: (Optional) Specifies that qfi informat
                      ion be included for end marker packets for DRB level forwarding. This parameter i
                      s applicable only for inter-RAT direct data forwarding handover (5G to LTE)
               :param release_path: (Optional) Enables/disables the release of gtpu pat
                      h on free of last remote tunnel. Path is released by default
               :param delay_dl_packet_after_ho: (Optional) Time in ms to delay the firs
                      t downlink packet sent by the core to target gnb after completion of Handover. Ap
                      pplicable to Xn, NG and  EPS to 5G handovers. The timer is started when the last
                      end maker (for all QoS flows or for the PDU session) is received by the core netw
                      ork and once started, downlink packets will be dropped until the expiry of the ti
                      mer.
               :param enable_gtpu_sn: (Optional) Enables GTP-U Sequence Number inclusio
                      n in bearer packets. Once enabled, GTP-U Sequence Number would be included in all
                       bearers of subsequent established PDU Sessions.
               :param delay_echo_resp: (Optional) Delay sending of GTP-U echo response on specified GTP-U path.
        delay_echo_resp=local_ip,remote_ip,time_to_delay
        local_ip - local endpoint ip address
        remote_ip - remote endpoint ip address
        time_to_delay - time to delay Echo Response message in msec
        Note: This option cannot be set if skip_echo_req is already set for same path.
               :param gtpu_error_no_teid_found: (Optional) Specifies if a GTP-U error i
                      ndication is sent towards the gNB on receipt of UL data packets with TEID for whi
                      ch corresponding tunnels are not present on UPF.
        """

        self._wtsemu_egate_controller.egate_command_executor(
            "upf_param", **kwargs
        )

