    def enb_x2_link_up(self, **kwargs):
        """
        :param enb: Initiated eNB/gNB id
        :param target: Identifier for peer eNodeB/gNodeB
        :param x2_link_addr: (Optional) IP:Port of the peer gnb. This can be use
               d if peer real(external) gnb has multiple x2 IPs configured (x2 parameter in set_
               gnb command) and user wants to setup x2 link with a specific peer IP (not require
               d if peer has only one x2 IP Configured). This should be one of the x2 IPs in x2
               parameter in set_gnb command. If duplicate_x2_setup_error parameter is set, then
               this validation is skipped and x2 setup is sent without validating that the IP is
                actually configured on the peer gnb.
        :param duplicate_x2_setup_error: (Optional) If this flag is set to true,
                then enbsim will try to establish a x2 link even if a x2 link already exists wit
               h the peer. If the IP adddress in x2_link_addr parameter is different from the re
               al peer gnb IP with which an x2 link already exists, then it is expected that the
                peer gnb rejects the duplicate x2 link setup. If peer real gnb accepts the dupli
               cate x2 link establishment, enbsim will send an error indication and stay with th
               e existing x2 link. If peer gnb does not respond to the duplicate x2 setup, enbsi
               m will timeout from the duplicate x2 link setup and stay with the previously setu
               p x2 link. If the IP address in x2_link_addr parameter is same (or x2_link_addr i
               s not provided) it is expected that the peer real gnb reestablishes the x2 link.
        """

        self._wtsemu_egate_controller.egate_command_executor(
            "enb_x2_link_up", **kwargs
        )

